// Récupère le prix et la disponibilité de chaque bien suivi, en testant
// jusqu'à 3 fenêtres de dates (base, base-flex_days, base+flex_days) et en
// retenant la moins chère parmi celles disponibles.
// Utilise l'endpoint GraphQL public d'Airbnb (StaysPdpBookItQuery) avec la
// clé API publique utilisée par le site lui-même (stable, non secrète).
const AIRBNB_API_KEY = 'd306zoyjsyarp7ifhu67rjxn52tv0t20';
const QUERY_HASH = '45cc0ada54da798665ac40417178a67be1378ca94275d37a2eca61ac1fb2cf7d';

function addDays(dateStr, days) {
  const d = new Date(dateStr + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

async function fetchWindow(listingIdB64, checkIn, checkOut, adults) {
  const variables = {
    id: listingIdB64,
    dateRange: { startDate: checkIn, endDate: checkOut },
    guestCounts: { numberOfAdults: adults },
    includePdpMigrationBookItCalendarSheetFragment: true,
    includePdpMigrationBookItFloatingFooterFragment: true,
    includePdpMigrationBookItNavFragment: true,
    includePdpMigrationBookItSidebarFragment: true,
    includeOverviewMerchandisingTipsFragment: true,
    includeStaysPdpPriceHeatmapFragment: false,
    priceHeatmapDateRange: { startDate: checkIn, endDate: checkOut },
    p3ImpressionId: 'p3_n8n_monitor',
    selectedCancellationPolicyId: null,
    causeId: null,
    selectedGuestOptionId: null
  };
  const extensions = { persistedQuery: { version: 1, sha256Hash: QUERY_HASH } };
  const url = `https://www.airbnb.com/api/v3/StaysPdpBookItQuery/${QUERY_HASH}?operationName=StaysPdpBookItQuery&locale=fr&currency=EUR&variables=${encodeURIComponent(JSON.stringify(variables))}&extensions=${encodeURIComponent(JSON.stringify(extensions))}`;

  const response = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: {
      'X-Airbnb-Api-Key': AIRBNB_API_KEY,
      'Accept': 'application/json',
      'Accept-Language': 'fr-FR,fr;q=0.9',
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36'
    },
    json: true
  });
  return response?.data?.node?.pdpPresentation?.bookIt || null;
}

const results = [];

for (const inputItem of $input.all()) {
  const d = inputItem.json;
  const listingId = String(d.listing_id || '').trim();
  const baseCheckIn = d.check_in;
  const baseCheckOut = d.check_out;
  const adults = Number(d.guests) || 2;
  const flexDays = Number(d.flex_days) || 0;

  if (!listingId || !baseCheckIn || !baseCheckOut) {
    results.push({ json: { ...d, fetch_error: 'listing_id, check_in ou check_out manquant', checked_at: new Date().toISOString() } });
    continue;
  }

  const listingIdB64 = Buffer.from(`DemandStayListing:${listingId}`).toString('base64');
  const offsets = flexDays > 0 ? [-flexDays, 0, flexDays] : [0];

  let best = null;
  let lastError = null;

  for (const offset of offsets) {
    const checkIn = addDays(baseCheckIn, offset);
    const checkOut = addDays(baseCheckOut, offset);

    try {
      const bookIt = await fetchWindow.call(this, listingIdB64, checkIn, checkOut, adults);
      const isAvailable = bookIt?.availability?.isAvailable ?? false;
      const priceFormatted = bookIt?.structuredDisplayPrice?.primaryLine?.price ?? null;
      const priceNumeric = priceFormatted ? Number(priceFormatted.replace(/[^0-9]/g, '')) : null;

      if (isAvailable && priceNumeric !== null) {
        if (!best || !best.available || priceNumeric < best.price) {
          best = { price: priceNumeric, priceFormatted, checkIn, checkOut, available: true };
        }
      } else if (!best) {
        best = { price: null, priceFormatted: null, checkIn, checkOut, available: false, unavailabilityMessage: bookIt?.availability?.unavailabilityMessage ?? null };
      }
    } catch (e) {
      lastError = e.message;
    }

    await new Promise((r) => setTimeout(r, 600));
  }

  results.push({
    json: {
      ...d,
      current_price_eur: best ? best.price : null,
      current_price_formatted: best ? best.priceFormatted : null,
      current_available: best ? best.available : null,
      matched_check_in: best ? best.checkIn : null,
      matched_check_out: best ? best.checkOut : null,
      unavailability_message: best ? (best.unavailabilityMessage || null) : null,
      checked_at: new Date().toISOString(),
      fetch_error: best ? null : lastError
    }
  });
}

return results;

// Compare le relevé actuel au dernier relevé connu, gère le compteur
// d'échecs consécutifs, et prépare le texte du message Slack.
const ERROR_ALERT_THRESHOLD = 3;
const results = [];

for (const item of $input.all()) {
  const d = item.json;
  const hadError = !!d.fetch_error;

  const lastPriceRaw = d.last_price_eur;
  const lastPrice = (lastPriceRaw === '' || lastPriceRaw === undefined || lastPriceRaw === null) ? null : Number(lastPriceRaw);

  const lastAvailableRaw = d.last_available;
  const hasLastAvailable = !(lastAvailableRaw === '' || lastAvailableRaw === undefined || lastAvailableRaw === null);
  const lastAvailable = hasLastAvailable ? (lastAvailableRaw === true || String(lastAvailableRaw).toLowerCase() === 'true') : null;

  const currentPrice = d.current_price_eur;
  const currentAvailable = d.current_available;

  const priceChanged = !hadError && currentPrice !== null && currentPrice !== undefined && lastPrice !== null && currentPrice !== lastPrice;
  const availabilityChanged = !hadError && currentAvailable !== null && currentAvailable !== undefined && hasLastAvailable && currentAvailable !== lastAvailable;

  const prevConsecutiveErrors = Number(d.consecutive_errors) || 0;
  const newConsecutiveErrors = hadError ? prevConsecutiveErrors + 1 : 0;
  const errorAlertTriggered = hadError && newConsecutiveErrors === ERROR_ALERT_THRESHOLD;

  let slackMessage = null;
  if (errorAlertTriggered) {
    slackMessage = `⚠️ *${d.name}*\nÉchec de vérification ${newConsecutiveErrors} fois de suite — à vérifier manuellement.\n🔗 ${d.url}`;
  } else if (priceChanged || availabilityChanged) {
    const lines = [`🔔 *${d.name}*`];
    if (priceChanged) lines.push(`💰 Prix : ${lastPrice}€ → ${currentPrice}€`);
    if (availabilityChanged) lines.push(`📅 Disponibilité : ${currentAvailable ? 'redevenu disponible ✅' : 'devenu indisponible ❌'}`);
    lines.push(`📆 ${d.matched_check_in || d.check_in} → ${d.matched_check_out || d.check_out}`);
    lines.push(`🔗 ${d.url}`);
    slackMessage = lines.join('\n');
  }

  results.push({
    json: {
      ...d,
      price_changed: priceChanged,
      availability_changed: availabilityChanged,
      consecutive_errors: newConsecutiveErrors,
      error_alert_triggered: errorAlertTriggered,
      has_alert: !!slackMessage,
      slack_message: slackMessage
    }
  });
}

return results;
